def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.9))
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    rich_threats = 0
    desperate_threats = 0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if bid >= 100:
                rich_threats += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            desperate_threats += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    units = supply / WATER_REQ
    tight_supply = units < 2.0
    very_tight_supply = units < 1.4

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(DAILY_SALARY * 0.95, highest_prev + 2.0, 90.0))
        return float(bid)

    if hp <= 4 or no_water_days >= 1:
        if rich_threats >= 2 and not very_tight_supply:
            bid = min(budget, DAILY_SALARY * 0.82)
        else:
            bid = min(budget, max(DAILY_SALARY * 0.78, min(highest_prev + 1.5, DAILY_SALARY * 1.15)))
        return float(bid)

    if rich_threats >= 2:
        if very_tight_supply:
            bid = min(budget, DAILY_SALARY * 0.72)
        else:
            bid = min(budget, DAILY_SALARY * 0.18)
        return float(bid)

    if highest_prev >= 85:
        if tight_supply and desperate_threats == 0:
            bid = min(budget, DAILY_SALARY * 0.62)
        else:
            bid = min(budget, DAILY_SALARY * 0.22)
        return float(bid)

    if highest_prev > 0:
        target = avg_prev + 2.0
        floor_bid = DAILY_SALARY * 0.42 if tight_supply else DAILY_SALARY * 0.34
        cap_bid = DAILY_SALARY * 0.78
        bid = min(budget, max(floor_bid, min(target, cap_bid)))
        if day >= 8 and hp >= 6:
            bid = min(bid, DAILY_SALARY * 0.3)
        return float(bid)

    if tight_supply:
        return float(min(budget, DAILY_SALARY * 0.5))
    return float(min(budget, DAILY_SALARY * 0.36))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid a minimal amount to secure water
    if not alive_opponents:
        return min(my_status['budget'], 1.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Decision logic based on yesterday's highest pressure
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If opponents are bidding very high relative to my salary
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: # I'm healthy, can take a risk to save budget
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            else: # I need water, bid aggressively
                return min(my_status['budget'], DAILY_SALARY * 0.95)
        else:
            # Match or slightly exceed the highest previous bid, but ensure a floor
            return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))
    else:
        # No previous bids (e.g., Day 1 or no bids from alive opponents yesterday)
        if my_status['hp'] <= 2: # Very low HP, need water desperately
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        else:
            # Default moderate bid
            return min(my_status['budget'], DAILY_SALARY * 0.55)

